<?php
namespace App\Domain\Articles; use App\Domain\PublicChrome\PublicAssetPath; use App\Models\Article; use Illuminate\Support\Facades\Cache; use Throwable; final class ArticleIndexViewData { public function get(int $page,?int $category):array{try{return Cache::remember('public.articles.index.v1.'.ArticleCache::indexVersion().'.'.now()->format('YmdHi').".$page.$category",now()->addMinutes(10),fn()=>$this->load($page,$category));}catch(Throwable){return $this->load($page,$category);}} private function load(int $page,?int $category):array{$p=Article::publiclyVisible()->with('category')->when($category,fn($q)=>$q->where('article_category_id',$category))->orderByDesc('is_featured')->orderBy('display_order')->paginate(12,['*'],'page',$page);return ['items'=>$p->getCollection()->map(fn($x)=>['title'=>$x->title,'excerpt'=>$x->excerpt,'category'=>$x->category?->is_active?$x->category->name:null,'image'=>PublicAssetPath::isSafe($x->featured_image_path)?$x->featured_image_path:null,'image_alt'=>$x->featured_image_alt,'date'=>($x->published_at?:$x->scheduled_for)?->toDateString(),'url'=>route('insights.show',$x->slug)])->all(),'pagination'=>['last'=>$p->lastPage(),'previous'=>$p->previousPageUrl(),'next'=>$p->nextPageUrl()]];} }
